const { EventEmitter } = require('events');

class ConnectionPool extends EventEmitter {
  constructor() {
    super();
    this.initialized = 0;
  }

  /**
   * Run `setup` exactly once, on the FIRST 'ready' event.
   * Later 'ready' events must not re-run it.
   */
  onFirstReady(setup) {
    this.on('ready', () => {
      this.initialized += 1;
      setup();
    });
  }
}

module.exports = { ConnectionPool };

