const assert = require('assert');
const { ConnectionPool } = require('./pool.js');

const pool = new ConnectionPool();
let calls = 0;
pool.onFirstReady(() => { calls += 1; });

pool.emit('ready');
pool.emit('ready');
pool.emit('ready');

assert.strictEqual(calls, 1, `setup ran ${calls} times, must be exactly once`);
assert.strictEqual(pool.initialized, 1, `initialized=${pool.initialized}, must be 1`);

// a second pool must be independent
const pool2 = new ConnectionPool();
let calls2 = 0;
pool2.onFirstReady(() => { calls2 += 1; });
pool2.emit('ready');
