const { EventEmitter } = require('events');

let initialized = false;

class ConnectionPool extends EventEmitter {
  constructor() {
    super();
    this.initialized = 0;
  }

  onFirstReady(setup) {
    this.on('ready', () => {
      if (initialized) return;
      initialized = true;
      this.initialized += 1;
      setup();
    });
  }
}

module.exports = { ConnectionPool };
